"""
Interfaces for LLM module to support dependency inversion and modularity.

This module defines clear contracts for LLM backends, caching, and chat sessions,
enabling decoupled implementations and improved testability.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from pathlib import Path
from typing import Any, Protocol, runtime_checkable


class ChatCache(ABC):
    """Interface for chat message caching."""

    @abstractmethod
    def chat_get(self, key: str) -> str | None:
        """Retrieve cached chat response for given key."""
        pass

    @abstractmethod
    def chat_set(self, key: str, value: str) -> None:
        """Store chat response in cache."""
        pass


class EmbeddingCache(ABC):
    """Interface for embedding caching."""

    @abstractmethod
    def embedding_get(self, key: str) -> list | dict | str | None:
        """Retrieve cached embedding for given key."""
        pass

    @abstractmethod
    def embedding_set(self, content_to_embedding_dict: dict) -> None:
        """Store embeddings in cache."""
        pass


class MessageCache(ABC):
    """Interface for conversation message history caching."""

    @abstractmethod
    def message_get(self, conversation_id: str) -> list[str]:
        """Retrieve message history for conversation."""
        pass

    @abstractmethod
    def message_set(self, conversation_id: str, message_value: list[str]) -> None:
        """Store message history for conversation."""
        pass


class LLMCache(ABC):
    """Interface for unified LLM caching (chat + embedding + message)."""

    @property
    @abstractmethod
    def chat_cache(self) -> ChatCache:
        """Chat cache instance."""
        pass

    @property
    @abstractmethod
    def embedding_cache(self) -> EmbeddingCache:
        """Embedding cache instance."""
        pass

    @property
    @abstractmethod
    def message_cache(self) -> MessageCache:
        """Message cache instance."""
        pass


class LLMBackend(ABC):
    """Interface for LLM API backends (OpenAI, Azure, Llama, etc.)."""

    @abstractmethod
    def create_chat_completion(
        self,
        messages: list[dict],
        **kwargs: Any,
    ) -> tuple[str, str | None]:
        """Execute chat completion and return (response, finish_reason)."""
        pass

    @abstractmethod
    def create_embedding(
        self,
        input_content: str | list[str],
        **kwargs: Any,
    ) -> list[Any] | Any:
        """Create embeddings for input content."""
        pass

    @abstractmethod
    def calculate_token_from_messages(self, messages: list[dict]) -> int:
        """Calculate token count for messages."""
        pass


class ChatSessionFactory(ABC):
    """Factory interface for creating chat sessions."""

    @abstractmethod
    def create_session(
        self,
        conversation_id: str | None = None,
        system_prompt: str | None = None,
    ) -> "ChatSession":
        """Create a new chat session."""
        pass


class ChatSession(ABC):
    """Interface for chat session management."""

    @property
    @abstractmethod
    def conversation_id(self) -> str:
        """Unique identifier for this conversation."""
        pass

    @abstractmethod
    def build_chat_completion(self, user_prompt: str, **kwargs: Any) -> str:
        """Build and execute a chat completion for the given prompt."""
        pass

    @abstractmethod
    def display_history(self) -> None:
        """Display conversation history."""
        pass


@runtime_checkable
class Cacheable(Protocol):
    """Protocol for objects that can be cached (chat, embedding, message)."""

    def __hash__(self) -> int: ...
    def __eq__(self, other: object) -> bool: ...


class ConversationManager(ABC):
    """Interface for conversation history management and export."""

    @abstractmethod
    def append(self, conv: tuple[list[dict], str]) -> None:
        """Append a conversation turn to history."""
        pass

    @abstractmethod
    def display(self) -> None:
        """Display conversation history."""
        pass


class TokenCounter(ABC):
    """Interface for token counting functionality."""

    @abstractmethod
    def count_tokens(self, text: str) -> int:
        """Count tokens in text."""
        pass

    @abstractmethod
    def count_messages_tokens(self, messages: list[dict]) -> int:
        """Count tokens in message list."""
        pass


class JSONParser(ABC):
    """Interface for robust JSON parsing."""

    @abstractmethod
    def parse(self, text: str, max_retries: int = 3) -> dict:
        """Parse JSON from potentially malformed text."""
        pass


class Configurable(ABC):
    """Interface for components that accept configuration."""

    @abstractmethod
    def configure(self, **kwargs: Any) -> None:
        """Apply configuration settings."""
        pass


class Retryable(ABC):
    """Interface for components with retry logic."""

    @abstractmethod
    def execute_with_retry(
        self,
        operation: str,
        max_retry: int,
        **kwargs: Any,
    ) -> Any:
        """Execute operation with retry logic."""
        pass


class SessionHistory(ABC):
    """Interface for conversation session history storage."""

    @abstractmethod
    def get_history(self, conversation_id: str) -> list[dict]:
        """Get full message history for conversation."""
        pass

    @abstractmethod
    def append_history(self, conversation_id: str, messages: list[dict]) -> None:
        """Append messages to conversation history."""
        pass


class EmbeddingDistanceCalculator(ABC):
    """Interface for embedding similarity calculations."""

    @abstractmethod
    def calculate_similarity(
        self,
        source_list: list[str],
        target_list: list[str],
    ) -> list[list[float]]:
        """Calculate similarity matrix between two lists."""
        pass


class LLMClientFactory(ABC):
    """Factory interface for LLM client creation."""

    @abstractmethod
    def create_backend(self, **kwargs: Any) -> LLMBackend:
        """Create an LLM backend instance."""
        pass

    @abstractmethod
    def create_cache(self, **kwargs: Any) -> LLMCache:
        """Create an LLM cache instance."""
        pass

    @abstractmethod
    def create_session_factory(self, backend: LLMBackend) -> ChatSessionFactory:
        """Create a chat session factory bound to a backend."""
        pass
